CREATE TABLE IF NOT EXISTS products (id text PRIMARY KEY, name text NOT NULL, category text NOT NULL DEFAULT 'skincare', category_label text NOT NULL DEFAULT 'العناية بالبشرة', short_description text NOT NULL DEFAULT '', long_description text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL CHECK (price >= 0), compare_at_price numeric(12,2) NOT NULL DEFAULT 0 CHECK (compare_at_price >= 0), stock integer NOT NULL DEFAULT 0 CHECK (stock >= 0), images jsonb NOT NULL DEFAULT '[]'::jsonb, active boolean NOT NULL DEFAULT true, featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now())